# VLA-only sources (eval-supp-spatial-vla-only-sXX or eval-supp-vla-only-spatial-sXX)
# Adaptive sources (eval-supp-adapt-tau025-spatial-sXX or eval-supp-spatial-adapt-tau025-sXX)

# Extract SR from metrics (handle various formats: percentage or 0-1 scale)
def get_sr(metrics):
    if not metrics:
        return None
    # Try various field names
    for key in ['overall_sr', 'overall_success_rate', 'success_rate', 'SR']:
        if key in metrics:
            val = metrics[key]
            if isinstance(val, (int, float)):
                if val <= 1.0:
                    return val * 100
                return val
    return None

# VLA-only data
vla_only = {}

# eval-supp-spatial-vla-only-s42 to s47
for seed in range(42, 50):
    key1 = f'eval-supp-spatial-vla-only-s{seed}'
    key2 = f'eval-supp-vla-only-spatial-s{seed}'

    if key1 in experiments_dict:
        exp = experiments_dict[key1]
        sr = get_sr(exp.get('metrics', {}))
        if sr is not None:
            vla_only[seed] = {'sr': sr, 'exp_id': key1, 'source': 'supp-clean'}

    if key2 in experiments_dict and seed not in vla_only:
        exp = experiments_dict[key2]
        sr = get_sr(exp.get('metrics', {}))
        if sr is not None:
            vla_only[seed] = {'sr': sr, 'exp_id': key2, 'source': 'supp-clean'}

# Adaptive data
adaptive = {}

for seed in range(42, 50):
    key1 = f'eval-supp-adapt-tau025-spatial-s{seed}'
    key1_r2 = f'eval-supp-adapt-tau025-spatial-s{seed}-r2'
    key2 = f'eval-supp-spatial-adapt-tau025-s{seed}'
    key2_r3 = f'eval-supp-spatial-adapt-tau025-s{seed}-r3'

    # Prefer r2/r3 versions (re-runs after fixing issues)
    for key in [key1_r2, key1, key2_r3, key2]:
        if key in experiments_dict:
            exp = experiments_dict[key]
            metrics = exp.get('metrics', {}) or {}
            sr = get_sr(metrics)
            if sr is not None and exp.get('conclusion') == 'success':
                if seed not in adaptive:
                    adaptive[seed] = {'sr': sr, 'exp_id': key, 'source': 'supp-clean'}
                    break

# Also check eval-supp-adapt-tau025-spatial-s47 which has overall_success_rate in metrics
# Let me also check if s46 data exists elsewhere
print('=== VLA-only data ===')
for seed in range(42, 50):
    if seed in vla_only:
        print(f'  s{seed}: SR={vla_only[seed][\"sr\"]}% | exp_id={vla_only[seed][\"exp_id\"]}')
    else:
        print(f'  s{seed}: MISSING')

print()
print('=== Adaptive data ===')
for seed in range(42, 50):
    if seed in adaptive:
        print(f'  s{seed}: SR={adaptive[seed][\"sr\"]}% | exp_id={adaptive[seed][\"exp_id\"]}')
    else:
        print(f'  s{seed}: MISSING')

print()

# Compute statistics for available pairs
paired_seeds = sorted(set(vla_only.keys()) & set(adaptive.keys()))
print(f'Available pairs: {len(paired_seeds)} seeds: {paired_seeds}')
print()

if len(paired_seeds) >= 2:
    vla_scores = [vla_only[s]['sr'] for s in paired_seeds]
    adapt_scores = [adaptive[s]['sr'] for s in paired_seeds]

    print('seed | VLA-only SR | Adaptive SR | Delta')
    for s in paired_seeds:
        delta = adaptive[s]['sr'] - vla_only[s]['sr']
        print(f's{s}  | {vla_only[s][\"sr\"]:>6.1f}%    | {adaptive[s][\"sr\"]:>6.1f}%    | {delta:+.1f}pp')

    print()
    t_stat, t_pval = stats.ttest_rel(adapt_scores, vla_scores)
    print(f'Paired t-test: t={t_stat:.4f}, p={t_pval:.6f}')

    w_stat, w_pval = stats.wilcoxon([adapt_scores[i] - vla_scores[i] for i in range(len(paired_seeds))])
    print(f'Wilcoxon signed-rank: W={w_stat:.1f}, p={w_pval:.6f}')
" 2>&1

